INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-01', 'owner', 'audio-itops-a2-01', 'A2-B1 | 01. Morning Server Check & Handover (IT Ops)', 'Simple shift handover between two junior operators checking server status, alerts, and daily tickets (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-1', 'lesson-audio-itops-a2-01', 'owner', 0, 5.5, 'Good morning Ben, how was the night shift in the server room?', '[Ca sáng] Chào buổi sáng Ben, ca trực đêm ở phòng máy chủ thế nào?', 'night shift, server room', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-2', 'lesson-audio-itops-a2-01', 'owner', 5.5, 11, 'It was very quiet, and all main servers are running normally today.', '[Ca đêm] Rất yên tĩnh, và tất cả máy chủ chính hôm nay đều đang chạy bình thường.', 'quiet, running normally', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-3', 'lesson-audio-itops-a2-01', 'owner', 11, 16.5, 'Did we get any red alerts on the monitoring screen last night?', '[Ca sáng] Đêm qua màn hình giám sát có báo cảnh báo đỏ nào không?', 'alerts, monitoring screen', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-4', 'lesson-audio-itops-a2-01', 'owner', 16.5, 22.8, 'We had one yellow warning on mail server two around three in the morning.', '[Ca đêm] Ta có một cảnh báo vàng ở máy chủ thư số hai vào khoảng ba giờ sáng.', 'warning, mail server', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-5', 'lesson-audio-itops-a2-01', 'owner', 22.8, 28.3, 'What caused that warning, and did you need to restart the machine?', '[Ca sáng] Nguyên nhân cảnh báo là gì, cậu có cần khởi động lại máy không?', 'caused, restart', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-6', 'lesson-audio-itops-a2-01', 'owner', 28.3, 35, 'The memory was briefly high during a backup job, then it went back to normal.', '[Ca đêm] Bộ nhớ tăng cao một lúc khi chạy sao lưu, sau đó tự trở lại bình thường.', 'briefly, backup job, normal', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-7', 'lesson-audio-itops-a2-01', 'owner', 35, 40.5, 'Great, are there any open support tickets waiting for the morning team?', '[Ca sáng] Tốt quá, còn phiếu hỗ trợ nào đang mở chờ ca sáng xử lý không?', 'support tickets, waiting', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-8', 'lesson-audio-itops-a2-01', 'owner', 40.5, 46.8, 'Only two small printer requests, and I already wrote short notes in our logbook.', '[Ca đêm] Chỉ còn hai yêu cầu máy in nhỏ thôi, mình đã ghi chú ngắn vào sổ trực rồi.', 'requests, notes, logbook', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-9', 'lesson-audio-itops-a2-01', 'owner', 46.8, 52.7, 'Thanks for the clear handover, Ben; go home and get some good rest.', '[Ca sáng] Cảm ơn bàn giao rõ ràng nhé Ben; về nhà nghỉ ngơi cho khỏe đi.', 'handover, rest', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-02', 'owner', 'audio-itops-a2-02', 'A2-B1 | 02. Locked Account & Password Reset Call (IT Support)', 'Everyday IT helpdesk phone call helping a staff member unlock an account and set a safe password (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-1', 'lesson-audio-itops-a2-02', 'owner', 0, 5, 'Hello, IT helpdesk speaking; how can I help you this morning?', '[Helpdesk] Xin chào, bộ phận hỗ trợ IT nghe ạ; sáng nay tôi có thể giúp gì cho bạn?', 'helpdesk, speaking', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-2', 'lesson-audio-itops-a2-02', 'owner', 5, 11.3, 'Hi, I cannot sign in to my work email because my account is locked.', '[Nhân viên] Chào bạn, tôi không đăng nhập được email công ty vì tài khoản bị khóa rồi.', 'sign in, locked', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-3', 'lesson-audio-itops-a2-02', 'owner', 11.3, 17.6, 'Do not worry, I can unlock it for you in just a few minutes.', '[Helpdesk] Đừng lo, tôi có thể mở khóa giúp bạn chỉ trong vài phút.', 'unlock, a few minutes', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-4', 'lesson-audio-itops-a2-02', 'owner', 17.6, 23.1, 'First, could you please tell me your full name and employee number?', '[Helpdesk] Trước tiên, bạn vui lòng cho tôi biết họ tên đầy đủ và mã nhân viên nhé?', 'full name, employee number', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-5', 'lesson-audio-itops-a2-02', 'owner', 23.1, 29.4, 'Sure, my name is Claire Evans, and my number is four zero eight two.', '[Nhân viên] Được ạ, tôi tên Claire Evans, mã nhân viên là 4082.', 'number', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-6', 'lesson-audio-itops-a2-02', 'owner', 29.4, 35.3, 'Thank you Claire; I see five wrong password attempts on your login screen.', '[Helpdesk] Cảm ơn Claire; tôi thấy có năm lần nhập sai mật khẩu trên màn hình đăng nhập của bạn.', 'wrong password, attempts, login screen', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-7', 'lesson-audio-itops-a2-02', 'owner', 35.3, 41.2, 'Yes, my keyboard had caps lock turned on, so I typed it wrong.', '[Nhân viên] Đúng rồi, bàn phím tôi đang bật phím viết hoa nên tôi gõ sai.', 'keyboard, caps lock, typed', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-8', 'lesson-audio-itops-a2-02', 'owner', 41.2, 47.1, 'I have unlocked your account and sent a temporary link to your phone.', '[Helpdesk] Tôi đã mở khóa tài khoản và gửi một đường dẫn tạm thời tới điện thoại của bạn.', 'temporary link', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-9', 'lesson-audio-itops-a2-02', 'owner', 47.1, 53, 'Please choose a strong new password with letters and numbers, then try again.', '[Helpdesk] Bạn hãy chọn mật khẩu mới mạnh có cả chữ và số rồi thử đăng nhập lại nhé.', 'strong password, letters, numbers', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-03', 'owner', 'audio-itops-a2-03', 'A2-B1 | 03. Slow Office WiFi & Router Restart (IT Support)', 'Practical workplace call diagnosing slow internet on the third floor, checking cables, and restarting the router (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-1', 'lesson-audio-itops-a2-03', 'owner', 0, 5.9, 'Hi Sam, the internet on the third floor is very slow this afternoon.', '[Nhân viên] Chào Sam, mạng internet ở tầng ba chiều nay rất chậm.', 'third floor, slow', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-2', 'lesson-audio-itops-a2-03', 'owner', 5.9, 12.2, 'Is it slow only on your laptop, or are your colleagues having trouble too?', '[IT Support] Chỉ chậm trên máy tính xách tay của bạn hay đồng nghiệp cũng gặp trục trặc?', 'laptop, colleagues, having trouble', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-3', 'lesson-audio-itops-a2-03', 'owner', 12.2, 18.1, 'Everyone near the meeting room keeps losing their video calls every few minutes.', '[Nhân viên] Mọi người gần phòng họp đều cứ bị rớt cuộc gọi video sau vài phút.', 'meeting room, losing, video calls', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-4', 'lesson-audio-itops-a2-03', 'owner', 18.1, 24.4, 'Let me check the network panel; the wireless router on your floor looks busy.', '[IT Support] Để tôi kiểm tra bảng điều khiển mạng; bộ phát WiFi ở tầng bạn có vẻ đang quá tải.', 'network panel, wireless router, busy', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-5', 'lesson-audio-itops-a2-03', 'owner', 24.4, 31.1, 'Could you look at the small white box on the wall and check the lights?', '[IT Support] Bạn có thể nhìn hộp trắng nhỏ trên tường và kiểm tra các đèn báo giúp tôi không?', 'box on the wall, lights', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-6', 'lesson-audio-itops-a2-03', 'owner', 31.1, 37.4, 'The power light is green, but the network light is blinking orange very fast.', '[Nhân viên] Đèn nguồn màu xanh lá, nhưng đèn mạng đang nhấp nháy màu cam rất nhanh.', 'power light, blinking orange', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-7', 'lesson-audio-itops-a2-03', 'owner', 37.4, 44.1, 'I will restart that access point remotely now, so WiFi will drop for one minute.', '[IT Support] Tôi sẽ khởi động lại điểm phát sóng đó từ xa ngay, nên WiFi sẽ ngắt khoảng một phút.', 'access point, remotely, drop', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-8', 'lesson-audio-itops-a2-03', 'owner', 44.1, 50.4, 'The orange light turned solid green, and our pages are loading fast again now.', '[Nhân viên] Đèn cam chuyển sang xanh đứng yên rồi, các trang web cũng tải nhanh lại ngay.', 'solid green, loading fast', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-04', 'owner', 'audio-itops-a2-04', 'A2-B1 | 04. Daily Backup Check & Free Disk Space (IT Ops)', 'Simple operations chat about checking last night''s backup status and cleaning up old temporary files (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-1', 'lesson-audio-itops-a2-04', 'owner', 0, 5.9, 'Hey Anna, did the nightly backup finish safely on our main file server?', '[Ops] Chào Anna, bản sao lưu hằng đêm trên máy chủ tệp chính có hoàn tất an toàn không?', 'nightly backup, file server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-2', 'lesson-audio-itops-a2-04', 'owner', 5.9, 12.2, 'Not completely; the backup stopped halfway because the storage drive ran out of space.', '[Junior Ops] Chưa hoàn toàn; bản sao lưu dừng giữa chừng vì ổ đĩa lưu trữ bị hết dung lượng.', 'stopped halfway, storage drive, ran out of space', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-3', 'lesson-audio-itops-a2-04', 'owner', 12.2, 18.5, 'Let us check which folder is taking up the most room on that drive.', '[Ops] Hãy kiểm tra xem thư mục nào đang chiếm nhiều chỗ nhất trên ổ đĩa đó.', 'folder, taking up, room', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-4', 'lesson-audio-itops-a2-04', 'owner', 18.5, 25.2, 'I see hundreds of old temporary files from last month still sitting inside the folder.', '[Junior Ops] Mình thấy hàng trăm tệp tạm cũ từ tháng trước vẫn còn nằm trong thư mục.', 'temporary files, sitting inside', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-5', 'lesson-audio-itops-a2-04', 'owner', 25.2, 31.1, 'Are any active users or programs still using those old files right now?', '[Ops] Có người dùng hay chương trình nào đang hoạt động còn dùng các tệp cũ đó không?', 'active users, programs', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-6', 'lesson-audio-itops-a2-04', 'owner', 31.1, 37.4, 'No, they are just finished export files that we only keep for seven days.', '[Junior Ops] Không, đó chỉ là các tệp xuất dữ liệu đã xong mà ta chỉ giữ lại bảy ngày.', 'export files, keep', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-7', 'lesson-audio-itops-a2-04', 'owner', 37.4, 43.7, 'Okay, delete the files older than two weeks and run the backup job again.', '[Ops] Được rồi, hãy xóa các tệp cũ hơn hai tuần rồi chạy lại tác vụ sao lưu nhé.', 'older than, backup job', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-8', 'lesson-audio-itops-a2-04', 'owner', 43.7, 50.4, 'We now have forty percent free space, and the new backup finished with zero errors.', '[Junior Ops] Giờ ta đã có 40% dung lượng trống, và bản sao lưu mới vừa chạy xong không lỗi nào.', 'free space, zero errors', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-05', 'owner', 'audio-itops-a2-05', 'A2-B1 | 05. Website Down? Basic First Checks (IT Ops)', 'Clear beginner IT Ops conversation walking through the first steps when a customer reports the company website is down (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-1', 'lesson-audio-itops-a2-05', 'owner', 0, 5.9, 'Tom, a client just messaged us saying our company website will not open.', '[Support] Tom ơi, một khách hàng vừa nhắn tin báo trang web công ty không mở được.', 'messaged, website', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-2', 'lesson-audio-itops-a2-05', 'owner', 5.9, 12.6, 'Let me test the address from my browser and check our public status page first.', '[Ops] Để mình thử mở địa chỉ từ trình duyệt và kiểm tra trang trạng thái công khai trước.', 'browser, status page', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-3', 'lesson-audio-itops-a2-05', 'owner', 12.6, 18.9, 'I see an error page too, so the problem is definitely on our side.', '[Ops] Mình cũng thấy trang báo lỗi, vậy chắc chắn sự cố nằm ở phía hệ thống của mình.', 'error page, definitely, on our side', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-4', 'lesson-audio-itops-a2-05', 'owner', 18.9, 25.2, 'Should we tell the manager right away, or check the web service logs first?', '[Support] Ta nên báo quản lý ngay lập tức, hay kiểm tra nhật ký dịch vụ web trước?', 'right away, service logs', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-5', 'lesson-audio-itops-a2-05', 'owner', 25.2, 31.9, 'Always check the service status first so we can share useful facts in our update.', '[Ops] Luôn kiểm tra trạng thái dịch vụ trước để ta chia sẻ thông tin hữu ích khi cập nhật.', 'service status, useful facts', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-6', 'lesson-audio-itops-a2-05', 'owner', 31.9, 38.6, 'Look here, the web service stopped five minutes ago right after a small setting change.', '[Ops] Nhìn đây này, dịch vụ web đã dừng năm phút trước ngay sau một thay đổi cài đặt nhỏ.', 'setting change', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-7', 'lesson-audio-itops-a2-05', 'owner', 38.6, 44.9, 'I will undo that setting change and start the web service back up cleanly.', '[Ops] Mình sẽ hoàn tác thay đổi cài đặt đó và khởi động lại dịch vụ web thật gọn.', 'undo, start back up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-8', 'lesson-audio-itops-a2-05', 'owner', 44.9, 52, 'The homepage is online again, and I will reply to the client with a quick apology.', '[Support] Trang chủ lên mạng lại rồi, để mình nhắn trả lời xin lỗi nhanh cho khách hàng.', 'homepage, online, apology', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-06', 'owner', 'audio-itops-a2-06', 'A2-B1 | 06. Planning a Weekend Software Update (IT Ops)', 'Clear A2-B1 workplace chat planning a Saturday night server update, notifying users, saving a backup, and running quick tests (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-1', 'lesson-audio-itops-a2-06', 'owner', 0, 6.3, 'Hi Maya, when should we install the new security update on our office servers?', '[SysAdmin] Chào Maya, khi nào ta nên cài bản cập nhật bảo mật mới trên các máy chủ văn phòng?', 'install, security update', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-2', 'lesson-audio-itops-a2-06', 'owner', 6.3, 12.6, 'Saturday night at eleven is best because nobody is working in the office then.', '[Ops Lead] Tối thứ Bảy lúc mười một giờ là tốt nhất vì lúc đó không ai làm việc ở văn phòng.', 'nobody, working', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-3', 'lesson-audio-itops-a2-06', 'owner', 12.6, 18.5, 'How long will the systems be offline while the servers install and restart?', '[SysAdmin] Các hệ thống sẽ tạm ngưng bao lâu trong lúc máy chủ cài đặt và khởi động lại?', 'offline, restart', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-4', 'lesson-audio-itops-a2-06', 'owner', 18.5, 24.4, 'Usually around twenty minutes, though we should tell staff to expect thirty minutes.', '[Ops Lead] Thường khoảng hai mươi phút, nhưng ta nên báo nhân viên dự phòng ba mươi phút.', 'usually, expect', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-5', 'lesson-audio-itops-a2-06', 'owner', 24.4, 30.3, 'I will send a short reminder email to every department on Friday morning.', '[SysAdmin] Tôi sẽ gửi một email nhắc nhở ngắn cho mọi phòng ban vào sáng thứ Sáu.', 'reminder email, department', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-6', 'lesson-audio-itops-a2-06', 'owner', 30.3, 36.2, 'Please also make a fresh backup copy before you press the update button.', '[Ops Lead] Nhớ tạo thêm một bản sao lưu mới trước khi bạn bấm nút cập nhật nhé.', 'fresh backup copy, press', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-7', 'lesson-audio-itops-a2-06', 'owner', 36.2, 42.1, 'Of course, if anything breaks, we can restore the old version very quickly.', '[SysAdmin] Chắc chắn rồi, nếu có gì hỏng ta có thể khôi phục phiên bản cũ rất nhanh.', 'breaks, restore, old version', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-8', 'lesson-audio-itops-a2-06', 'owner', 42.1, 49.2, 'After the restart finishes, test login and email once, then post a green check in chat.', '[Ops Lead] Sau khi khởi động lại xong, hãy thử đăng nhập và email một lần rồi nhắn báo xanh vào nhóm chat nhé.', 'test login, post', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-07', 'owner', 'audio-itops-a2-07', 'A2-B1 | 07. High CPU Alert on Web Server (IT Ops)', 'Simple on-call call checking a high CPU alert on a live web server, moving traffic away, and safely restarting the app (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-1', 'lesson-audio-itops-a2-07', 'owner', 0, 6.7, 'Hi Mark, sorry to call late, but web server three just hit ninety percent CPU.', '[NOC] Chào Mark, xin lỗi đã gọi muộn, nhưng máy chủ web số ba vừa chạm 90% CPU.', 'call late, web server, ninety percent', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-2', 'lesson-audio-itops-a2-07', 'owner', 6.7, 12.2, 'I am opening the monitoring screen now; are customer pages loading slowly?', '[Ops] Tôi đang mở màn hình giám sát; trang của khách hàng có đang tải chậm không?', 'monitoring screen, loading slowly', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-3', 'lesson-audio-itops-a2-07', 'owner', 12.2, 17.7, 'Yes, pages take three seconds to open, and memory keeps going up.', '[NOC] Có, trang mất ba giây để mở, và bộ nhớ cứ tiếp tục tăng lên.', 'three seconds, memory, going up', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-4', 'lesson-audio-itops-a2-07', 'owner', 17.7, 23.6, 'That sounds like the app is using too much memory after tonight’s update.', '[Ops] Nghe có vẻ ứng dụng đang dùng quá nhiều bộ nhớ sau bản cập nhật tối nay.', 'too much memory, update', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-5', 'lesson-audio-itops-a2-07', 'owner', 23.6, 29.5, 'Should I restart the web service right now to bring the CPU down?', '[NOC] Tôi có nên khởi động lại dịch vụ web ngay để hạ CPU xuống không?', 'restart, web service, bring down', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-6', 'lesson-audio-itops-a2-07', 'owner', 29.5, 36.2, 'Wait a moment; move users to our other servers first so nobody gets cut off.', '[Ops] Chờ một chút; hãy chuyển người dùng sang các máy chủ khác trước để không ai bị ngắt kết nối.', 'move users, cut off', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-7', 'lesson-audio-itops-a2-07', 'owner', 36.2, 42.9, 'Okay, traffic is safely moved, and I saved a quick log file for your review.', '[NOC] Rồi, lưu lượng đã được chuyển an toàn, và tôi đã lưu nhanh tệp log để anh xem.', 'safely moved, log file, review', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-8', 'lesson-audio-itops-a2-07', 'owner', 42.9, 48.8, 'Great, now switch back to the earlier version and watch the CPU graph.', '[Ops] Tuyệt, giờ hãy quay về phiên bản trước đó và theo dõi biểu đồ CPU nhé.', 'switch back, earlier version, graph', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-07-seg-9', 'lesson-audio-itops-a2-07', 'owner', 48.8, 54.3, 'Done, CPU dropped to twenty percent, and the website feels fast again.', '[NOC] Xong rồi, CPU giảm xuống 20% và trang web lại chạy nhanh trở lại.', 'dropped, fast again', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-08', 'owner', 'audio-itops-a2-08', 'A2-B1 | 08. Website Security Warning & SSL Fix (IT Ops)', 'Clear workplace call fixing an expired website security certificate after users report a browser warning (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-1', 'lesson-audio-itops-a2-08', 'owner', 0, 6.7, 'Hello Sarah, customers are calling because browsers show a red security warning on our site.', '[Helpdesk] Chào Sarah, khách hàng đang gọi báo trình duyệt hiện cảnh báo bảo mật màu đỏ trên trang của mình.', 'browsers, security warning', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-2', 'lesson-audio-itops-a2-08', 'owner', 6.7, 13.8, 'Let me check the website lock icon; oh no, our SSL certificate expired ten minutes ago.', '[Infra] Để tôi kiểm tra biểu tượng ổ khóa trang web; ôi không, chứng chỉ SSL của ta vừa hết hạn mười phút trước.', 'lock icon, SSL certificate, expired', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-3', 'lesson-audio-itops-a2-08', 'owner', 13.8, 19.3, 'I thought our server updated every security certificate automatically before it ended.', '[Helpdesk] Tôi tưởng máy chủ tự động cập nhật mọi chứng chỉ bảo mật trước khi hết hạn chứ.', 'updated, automatically', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-4', 'lesson-audio-itops-a2-08', 'owner', 19.3, 25.6, 'A firewall rule blocked the check yesterday, so the auto update did not finish.', '[Infra] Một quy tắc tường lửa đã chặn bước kiểm tra hôm qua, nên việc tự cập nhật không chạy xong.', 'firewall rule, blocked, auto update', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-5', 'lesson-audio-itops-a2-08', 'owner', 25.6, 32.7, 'How quickly can we fix the site without kicking out users who are already logged in?', '[Helpdesk] Ta có thể sửa trang web nhanh cỡ nào mà không đẩy người dùng đang đăng nhập ra ngoài?', 'kicking out, logged in', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-6', 'lesson-audio-itops-a2-08', 'owner', 32.7, 39, 'I am uploading the new certificate file to our main web server right now.', '[Infra] Tôi đang tải tệp chứng chỉ mới lên máy chủ web chính ngay bây giờ.', 'uploading, certificate file', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-7', 'lesson-audio-itops-a2-08', 'owner', 39, 45.3, 'Next, I will reload the web server softly so current sessions keep working smoothly.', '[Infra] Tiếp theo, tôi sẽ nạp lại máy chủ web nhẹ nhàng để các phiên hiện tại vẫn chạy mượt.', 'reload, current sessions, smoothly', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-08-seg-8', 'lesson-audio-itops-a2-08', 'owner', 45.3, 53.3, 'The lock icon is green again; let us add a reminder thirty days before it expires next time.', '[Helpdesk] Biểu tượng ổ khóa đã xanh trở lại; lần tới nhớ thêm nhắc nhở trước 30 ngày hết hạn nhé.', 'green again, reminder, thirty days', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-09', 'owner', 'audio-itops-a2-09', 'A2-B1 | 09. Large Log Files Filling Up Disk Space (IT Ops)', 'Straightforward Linux operations call finding a huge debug log file on a full disk and clearing it safely (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-1', 'lesson-audio-itops-a2-09', 'owner', 0, 6.7, 'Hey Kevin, our billing server stopped saving new orders and sent a full disk alert.', '[Monitoring] Chào Kevin, máy chủ thanh toán vừa ngừng lưu đơn hàng mới và gửi cảnh báo đầy ổ đĩa.', 'billing server, full disk alert', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-2', 'lesson-audio-itops-a2-09', 'owner', 6.7, 13.4, 'I just checked the drive, and the main system disk is one hundred percent full.', '[SysAdmin] Tôi vừa kiểm tra ổ đĩa, và ổ hệ thống chính đã đầy 100%.', 'checked the drive, system disk', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-3', 'lesson-audio-itops-a2-09', 'owner', 13.4, 19.3, 'Did customer orders grow suddenly, or is another file taking all the space?', '[Monitoring] Do đơn hàng tăng đột ngột, hay có tệp nào khác đang chiếm hết dung lượng?', 'grow suddenly, taking all the space', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-4', 'lesson-audio-itops-a2-09', 'owner', 19.3, 25.2, 'Someone left detailed error logging turned on, creating one huge forty gigabyte file.', '[SysAdmin] Ai đó quên tắt chế độ ghi log lỗi chi tiết, tạo ra một tệp khổng lồ nặng 40 gigabyte.', 'error logging, huge, gigabyte', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-5', 'lesson-audio-itops-a2-09', 'owner', 25.2, 31.9, 'Can we simply delete that big log file right now to get our space back?', '[Monitoring] Ta có thể xóa thẳng tệp log lớn đó ngay để lấy lại dung lượng không?', 'simply delete, get space back', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-6', 'lesson-audio-itops-a2-09', 'owner', 31.9, 37.8, 'Not directly, because the running app is still writing to that open file.', '[SysAdmin] Không xóa trực tiếp được, vì ứng dụng đang chạy vẫn đang ghi vào tệp đang mở đó.', 'directly, running app, open file', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-7', 'lesson-audio-itops-a2-09', 'owner', 37.8, 44.1, 'Instead, I will clear the file content safely and turn off extra debug logs.', '[SysAdmin] Thay vào đó, tôi sẽ làm rỗng nội dung tệp an toàn và tắt chế độ ghi log gỡ lỗi thừa.', 'clear content, safely, debug logs', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-09-seg-8', 'lesson-audio-itops-a2-09', 'owner', 44.1, 50.8, 'Orders are saving again right away; tomorrow let us set up automatic daily log cleanup.', '[Monitoring] Đơn hàng đã lưu lại được ngay; ngày mai ta hãy cài dọn log tự động hằng ngày nhé.', 'right away, daily log cleanup', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-10', 'owner', 'audio-itops-a2-10', 'A2-B1 | 10. Slow Database & Waiting Customer Orders (IT Ops)', 'Clear incident call between Support and a Database Admin stopping a heavy report that is slowing down customer checkout (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-1', 'lesson-audio-itops-a2-10', 'owner', 0, 6.3, 'Hi Priya, customers say the checkout page keeps spinning and never finishes their order.', '[Support] Chào Priya, khách hàng báo trang thanh toán cứ xoay mãi mà không hoàn tất đơn hàng.', 'checkout page, spinning, order', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-2', 'lesson-audio-itops-a2-10', 'owner', 6.3, 13, 'I see many database requests waiting in line because a big sales report is running.', '[DBA] Tôi thấy nhiều yêu cầu cơ sở dữ liệu đang xếp hàng chờ vì một báo cáo doanh số lớn đang chạy.', 'waiting in line, sales report', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-3', 'lesson-audio-itops-a2-10', 'owner', 13, 18.5, 'Why is that sales report taking almost one minute to finish today?', '[Support] Tại sao hôm nay báo cáo doanh số đó lại mất gần một phút mới chạy xong vậy?', 'almost one minute, finish', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-4', 'lesson-audio-itops-a2-10', 'owner', 18.5, 26, 'It is reading five million rows one by one because the table is missing a search index.', '[DBA] Nó đang đọc từng dòng qua năm triệu bản ghi vì bảng đó bị thiếu chỉ mục tìm kiếm.', 'five million rows, missing, search index', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-5', 'lesson-audio-itops-a2-10', 'owner', 26, 32.3, 'Can we stop that slow report first so live customer orders can go through?', '[Support] Ta có thể dừng báo cáo chậm đó trước để đơn hàng của khách đi qua được không?', 'stop, live orders, go through', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-6', 'lesson-audio-itops-a2-10', 'owner', 32.3, 39, 'Done, the waiting queue just cleared, and I moved reports to our backup read server.', '[DBA] Xong rồi, hàng chờ vừa thông thoáng, và tôi đã chuyển báo cáo sang máy chủ đọc dự phòng.', 'waiting queue, cleared, backup read server', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-7', 'lesson-audio-itops-a2-10', 'owner', 39, 44.5, 'Should we add the missing index tonight when the shop is quiet?', '[Support] Ta có nên thêm chỉ mục còn thiếu vào tối nay khi cửa hàng vắng khách không?', 'tonight, quiet', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-10-seg-8', 'lesson-audio-itops-a2-10', 'owner', 44.5, 50.4, 'Yes, I will add it carefully tonight without stopping the website at all.', '[DBA] Có, tối nay tôi sẽ thêm cẩn thận mà không cần dừng trang web chút nào.', 'carefully, without stopping', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-12', 'owner', 'audio-itops-a2-12', 'A2-B1 | 12. New App Update Crashing After Release (IT Ops)', 'Simple DevOps release call diagnosing a crashing payment service after deployment, finding a missing key, and rolling back (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-1', 'lesson-audio-itops-a2-12', 'owner', 0, 7.1, 'Elena, right after we pushed the new payment update, the app started crashing every ten seconds.', '[Release] Elena ơi, ngay sau khi ta đẩy bản cập nhật thanh toán mới, ứng dụng bắt đầu bị sập mỗi mười giây.', 'pushed, payment update, crashing', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-2', 'lesson-audio-itops-a2-12', 'owner', 7.1, 13.4, 'Pause the rollout right now; are the old app servers still serving our customers?', '[DevOps] Tạm dừng triển khai ngay; các máy chủ ứng dụng cũ có vẫn đang phục vụ khách hàng không?', 'pause, rollout, serving', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-3', 'lesson-audio-itops-a2-12', 'owner', 13.4, 19.7, 'Yes, the system blocked the broken servers automatically, so customers have not noticed yet.', '[Release] Có, hệ thống đã tự động chặn các máy chủ bị lỗi nên khách hàng vẫn chưa nhận ra.', 'broken servers, noticed', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-4', 'lesson-audio-itops-a2-12', 'owner', 19.7, 26.4, 'I am reading the error logs now to see why the new version keeps stopping.', '[DevOps] Tôi đang đọc nhật ký lỗi để xem vì sao phiên bản mới cứ tự dừng.', 'error logs, keeps stopping', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-5', 'lesson-audio-itops-a2-12', 'owner', 26.4, 32.7, 'Is the app running out of memory, or did a setting file go missing?', '[Release] Ứng dụng bị hết bộ nhớ, hay có tệp cài đặt nào bị thiếu vậy?', 'running out of memory, setting file', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-6', 'lesson-audio-itops-a2-12', 'owner', 32.7, 39.4, 'Memory is totally fine; the app crashed because one payment password is missing in settings.', '[DevOps] Bộ nhớ hoàn toàn ổn; ứng dụng sập vì thiếu một mật khẩu thanh toán trong phần cài đặt.', 'totally fine, missing in settings', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-7', 'lesson-audio-itops-a2-12', 'owner', 39.4, 46.1, 'Let us roll back to the previous version now so everything stays clean and safe.', '[Release] Hãy quay lại phiên bản trước ngay để mọi thứ luôn gọn gàng và an toàn.', 'roll back, previous version', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-12-seg-8', 'lesson-audio-itops-a2-12', 'owner', 46.1, 53.2, 'Rollback is complete, all servers are green, and we will double check settings before trying tomorrow.', '[DevOps] Hoàn tác xong rồi, mọi máy chủ đều xanh, và ta sẽ kiểm tra kỹ cài đặt trước khi thử lại vào ngày mai.', 'rollback, double check, tomorrow', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-14', 'owner', 'audio-itops-a2-14', 'A2-B1 | 14. Blocking Strange Login Attempts on Server (IT Ops)', 'A2-B1 security call blocking repeated failed SSH login attempts at the firewall and disabling password logins (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-1', 'lesson-audio-itops-a2-14', 'owner', 0, 6.7, 'Hi Leo, our security tool just reported thousands of failed logins on edge server two.', '[SOC] Chào Leo, công cụ bảo mật vừa báo hàng nghìn lượt đăng nhập thất bại trên máy chủ biên số hai.', 'security tool, failed logins', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-2', 'lesson-audio-itops-a2-14', 'owner', 6.7, 13, 'Thanks for telling me quickly; did any unknown user actually get into the server?', '[SysOps] Cảm ơn đã báo sớm; có người dùng lạ nào thực sự vào được máy chủ không?', 'unknown user, get into', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-3', 'lesson-audio-itops-a2-14', 'owner', 13, 20.1, 'No one got in yet, but the login attempts are coming from many strange foreign addresses.', '[SOC] Chưa ai vào được, nhưng các lượt đăng nhập đến từ nhiều địa chỉ nước ngoài lạ.', 'login attempts, foreign addresses', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-4', 'lesson-audio-itops-a2-14', 'owner', 20.1, 27.6, 'I am adding a block rule on our main firewall right now to stop all of them.', '[SysOps] Tôi đang thêm quy tắc chặn trên tường lửa chính ngay để dừng tất cả các địa chỉ đó.', 'block rule, main firewall', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-5', 'lesson-audio-itops-a2-14', 'owner', 27.6, 34.3, 'Why was the admin login port open to the public internet in the first place?', '[SOC] Ngay từ đầu tại sao cổng đăng nhập quản trị lại mở ra internet công cộng vậy?', 'admin port, public internet', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-6', 'lesson-audio-itops-a2-14', 'owner', 34.3, 41, 'An outside helper opened it during setup last week and forgot to close it afterwards.', '[SysOps] Một kỹ thuật viên bên ngoài đã mở nó lúc cài đặt tuần trước và quên đóng lại sau đó.', 'outside helper, forgot to close', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-7', 'lesson-audio-itops-a2-14', 'owner', 41, 46.9, 'Please turn off normal password login so only approved security keys can connect.', '[SOC] Vui lòng tắt đăng nhập bằng mật khẩu thường để chỉ các khóa bảo mật được duyệt mới kết nối được.', 'password login, security keys', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-14-seg-8', 'lesson-audio-itops-a2-14', 'owner', 46.9, 54.4, 'Done, the firewall is locked down, old keys are replaced, and the alert count dropped to zero.', '[SysOps] Xong rồi, tường lửa đã khóa chặt, khóa cũ đã thay mới và số cảnh báo đã giảm về không.', 'locked down, replaced, zero', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-01', 'owner', 'audio-itops-b1-01', 'B1 | 01. Investigating High Memory Usage on Production (IT Ops)', 'A 2-minute B1 IT Operations call tracking steady memory growth on a production server, moving traffic safely, and recovering after a release (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-1', 'lesson-audio-itops-b1-01', 'owner', 0, 7.1, 'Hello, I am calling because memory usage on application server two just passed eighty five percent.', '[Monitoring] Alo, mình gọi báo là RAM trên server ứng dụng số 2 vừa vượt quá 85% rồi.', 'memory usage, application server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-2', 'lesson-audio-itops-b1-01', 'owner', 7.1, 14.6, 'Thanks for telling me early; did the jump happen suddenly, or has it been going up slowly?', '[SysAdmin] Cảm ơn đã báo sớm nhé; nó tăng vọt đột ngột hay tăng dần từ từ vậy?', 'suddenly, going up slowly', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-3', 'lesson-audio-itops-b1-01', 'owner', 14.6, 20.9, 'Looking at the chart, memory started rising steadily right after last night’s software update.', '[Monitoring] Nhìn trên biểu đồ thì RAM bắt đầu tăng đều ngay sau đợt cập nhật phần mềm tối qua.', 'chart, rising steadily, software update', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-4', 'lesson-audio-itops-b1-01', 'owner', 20.9, 26.4, 'Are the other application servers showing the same rise on the dashboard?', '[SysAdmin] Các server ứng dụng khác trên dashboard có bị tăng giống vậy không?', 'same rise, dashboard', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-5', 'lesson-audio-itops-b1-01', 'owner', 26.4, 33.1, 'Yes, server one is already at seventy eight percent, and server three is close behind.', '[Monitoring] Có đó, server 1 đã lên 78% rồi, còn server 3 cũng sắp tới mức đó.', 'close behind', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-6', 'lesson-audio-itops-b1-01', 'owner', 33.1, 39.4, 'That clearly shows the new version is not freeing memory after finishing background tasks.', '[SysAdmin] Vậy rõ ràng là bản mới không giải phóng RAM sau khi chạy xong các tác vụ nền rồi.', 'clearly shows, freeing memory, background tasks', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-7', 'lesson-audio-itops-b1-01', 'owner', 39.4, 45.7, 'Are customers seeing slow page loads or error messages on the website right now?', '[SysAdmin] Hiện tại khách hàng vào web có bị tải chậm hay gặp thông báo lỗi gì chưa?', 'page loads, error messages', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-8', 'lesson-audio-itops-b1-01', 'owner', 45.7, 52.8, 'Not yet, response times are still normal, though we might hit the limit within two hours.', '[Monitoring] Chưa đâu, tốc độ phản hồi vẫn bình thường, nhưng khoảng hai tiếng nữa là có thể chạm ngưỡng.', 'response times, hit the limit', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-9', 'lesson-audio-itops-b1-01', 'owner', 52.8, 59.5, 'Let us act before users notice; first, remove server two from the active load balancer.', '[SysAdmin] Mình xử lý trước khi người dùng nhận ra nhé; trước hết tách server 2 ra khỏi load balancer đang chạy đi.', 'act before, load balancer', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-10', 'lesson-audio-itops-b1-01', 'owner', 59.5, 65.8, 'Should I wait for current user sessions to finish before stopping the application service?', '[Monitoring] Có cần đợi các phiên người dùng đang mở xong hẳn rồi mới tắt service ứng dụng không?', 'user sessions, application service', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-11', 'lesson-audio-itops-b1-01', 'owner', 65.8, 72.5, 'Yes, give it thirty seconds to finish current connections so nobody loses their shopping cart.', '[SysAdmin] Có chứ, đợi 30 giây cho các kết nối hiện tại xử lý xong để không ai bị mất giỏ hàng.', 'current connections, shopping cart', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-12', 'lesson-audio-itops-b1-01', 'owner', 72.5, 80.5, 'Server two has no active users now; do you want a quick memory report before I restart it?', '[Monitoring] Server 2 hết người dùng kết nối rồi; bạn có cần xuất nhanh báo cáo bộ nhớ trước khi mình khởi động lại không?', 'active users, memory report', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-13', 'lesson-audio-itops-b1-01', 'owner', 80.5, 86.4, 'Please save the process list and memory report into our shared support folder.', '[SysAdmin] Lưu giúp mình danh sách tiến trình với báo cáo bộ nhớ vào thư mục hỗ trợ dùng chung nhé.', 'process list, support folder', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-14', 'lesson-audio-itops-b1-01', 'owner', 86.4, 93.5, 'Both files are saved cleanly, and I am restarting the service on server two right now.', '[Monitoring] Mình lưu xong cả hai file rồi, giờ đang khởi động lại service trên server 2 đây.', 'saved cleanly', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-15', 'lesson-audio-itops-b1-01', 'owner', 93.5, 101, 'Once health checks pass, add server two back, then we will return to the previous stable version.', '[SysAdmin] Đợi health check báo xanh thì đưa server 2 vào lại, xong mình quay về phiên bản ổn định trước đó nhé.', 'health checks, stable version', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-16', 'lesson-audio-itops-b1-01', 'owner', 101, 107.7, 'Server two is healthy at thirty percent memory, and I am updating server one next.', '[Monitoring] Server 2 ổn rồi, RAM xuống còn 30%, giờ mình làm tiếp sang server 1.', 'healthy, updating', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-17', 'lesson-audio-itops-b1-01', 'owner', 107.7, 115.2, 'I will share the memory report with the development team so they can fix the problem today.', '[SysAdmin] Để mình gửi báo cáo bộ nhớ cho team dev để họ sửa lỗi ngay hôm nay.', 'development team, fix the problem', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-18', 'lesson-audio-itops-b1-01', 'owner', 115.2, 123.2, 'All three servers are stable again, and I will keep watching the memory chart for the next hour.', '[Monitoring] Cả ba server đều ổn định lại rồi, mình sẽ theo dõi thêm biểu đồ RAM trong một tiếng nữa cho chắc.', 'keep watching, next hour', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-02', 'owner', 'audio-itops-b1-02', 'B1 | 02. Fixing a Broken VPN Tunnel for Branch Office (IT Ops)', 'A 2-minute B1 networking conversation fixing a disconnected site-to-site VPN tunnel, expired shared key, and network checks (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-1', 'lesson-audio-itops-b1-02', 'owner', 0, 6.3, 'Hello, staff at our Manchester office cannot open the internal finance system this morning.', '[Branch Support] Alo, sáng nay nhân viên bên văn phòng Manchester không mở được hệ thống tài chính nội bộ.', 'office, internal finance system', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-2', 'lesson-audio-itops-b1-02', 'owner', 6.3, 13, 'Can they still open normal public websites, or is the whole office internet connection down?', '[Network Eng] Mọi người vẫn vào các trang web bên ngoài bình thường hay cả mạng văn phòng bị mất luôn?', 'public websites, connection down', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-3', 'lesson-audio-itops-b1-02', 'owner', 13, 19.7, 'Public websites work fine, and office email loads quickly, so only internal tools are failing.', '[Branch Support] Web ngoài vẫn vào bình thường, email công ty cũng chạy nhanh, chỉ có các hệ thống nội bộ là lỗi thôi.', 'internal tools, failing', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-4', 'lesson-audio-itops-b1-02', 'owner', 19.7, 27.2, 'That sounds like a problem with the secure VPN tunnel between Manchester and our main data centre.', '[Network Eng] Nghe giống bị lỗi đường kết nối VPN giữa chi nhánh Manchester với trung tâm dữ liệu chính rồi.', 'VPN tunnel, data centre', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-5', 'lesson-audio-itops-b1-02', 'owner', 27.2, 33.9, 'Let me log into the main network gateway and check the tunnel status right away.', '[Network Eng] Để mình đăng nhập vào thiết bị gateway chính kiểm tra trạng thái kết nối VPN ngay.', 'network gateway, tunnel status', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-6', 'lesson-audio-itops-b1-02', 'owner', 33.9, 40.6, 'Yes, the tunnel went offline at six thirty this morning and keeps failing to reconnect.', '[Network Eng] Đúng rồi, kết nối VPN bị ngắt từ 6 giờ 30 sáng nay và tự kết nối lại hoài không được.', 'went offline, reconnect', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-7', 'lesson-audio-itops-b1-02', 'owner', 40.6, 48.1, 'Did someone change the office firewall rules last night, or did the internet provider have an issue?', '[Branch Support] Tối qua có ai chỉnh luật firewall ở văn phòng không, hay do bên nhà mạng gặp trục trặc?', 'firewall rules, internet provider', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-8', 'lesson-audio-itops-b1-02', 'owner', 48.1, 54.4, 'The gateway logs show a login error because the shared security key expired today.', '[Network Eng] Log trên gateway báo lỗi xác thực vì khóa bảo mật dùng chung vừa hết hạn hôm nay.', 'shared security key, expired', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-9', 'lesson-audio-itops-b1-02', 'owner', 54.4, 60.3, 'I did not know those tunnel keys had a fixed yearly expiry date.', '[Branch Support] Mình không biết là mấy khóa VPN đó có hạn cố định theo từng năm luôn đấy.', 'yearly, expiry date', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-10', 'lesson-audio-itops-b1-02', 'owner', 60.3, 67.4, 'We change them every twelve months for security, and the reminder ticket was missed last week.', '[Network Eng] Bên mình đổi định kỳ mỗi 12 tháng để đảm bảo bảo mật, mà tuần trước bị sót mất ticket nhắc lịch.', 'reminder ticket, missed', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-11', 'lesson-audio-itops-b1-02', 'owner', 67.4, 75.8, 'Can you update the key from the main office, or do I need to plug into the local router?', '[Branch Support] Bạn cập nhật khóa từ văn phòng chính được không, hay mình phải cắm dây trực tiếp vào router ở đây?', 'main office, local router', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-12', 'lesson-audio-itops-b1-02', 'owner', 75.8, 82.9, 'I can reach the branch router over our backup management line, so no cables are needed.', '[Network Eng] Mình truy cập được router chi nhánh qua đường quản trị dự phòng nên không cần cắm dây đâu.', 'backup management line, cables', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-13', 'lesson-audio-itops-b1-02', 'owner', 82.9, 89.6, 'I just created a fresh key and saved the matching settings on both gateway devices.', '[Network Eng] Mình vừa tạo khóa mới và cấu hình khớp nhau trên cả hai đầu gateway rồi.', 'fresh key, matching settings', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-14', 'lesson-audio-itops-b1-02', 'owner', 89.6, 96.7, 'Now I am restarting the tunnel link; give it twenty seconds to build the secure connection.', '[Network Eng] Giờ mình khởi động lại kết nối VPN nhé; đợi khoảng 20 giây để hai đầu bắt tay mã hóa.', 'restarting, secure connection', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-15', 'lesson-audio-itops-b1-02', 'owner', 96.7, 104.2, 'The status light just turned green on my screen, and test pings are returning in twelve milliseconds.', '[Network Eng] Đèn trạng thái trên màn hình vừa chuyển xanh rồi, ping thử phản hồi chỉ 12 mili giây thôi.', 'test pings, milliseconds', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-16', 'lesson-audio-itops-b1-02', 'owner', 104.2, 111.3, 'Let me ask the finance team to refresh their browsers and sign in again right now.', '[Branch Support] Để mình nhắn team tài chính tải lại trình duyệt và đăng nhập lại xem sao.', 'refresh, sign in', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-17', 'lesson-audio-itops-b1-02', 'owner', 111.3, 118, 'They said the invoices are loading smoothly, and the shared network drive is visible again.', '[Branch Support] Họ báo hóa đơn tải mượt rồi, ổ đĩa mạng dùng chung cũng hiện lại bình thường.', 'loading smoothly, shared network drive', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-18', 'lesson-audio-itops-b1-02', 'owner', 118, 124.7, 'Great; I will set an automatic calendar reminder thirty days before next year’s key update.', '[Network Eng] Tốt quá; để mình đặt lịch nhắc tự động trước 30 ngày cho đợt đổi khóa năm sau.', 'calendar reminder, key update', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-03', 'owner', 'audio-itops-b1-03', 'B1 | 03. Handling a Sudden Traffic Spike During Sales (IT Ops)', 'A 2-minute B1 cloud operations call handling a flash-sale traffic jump with extra web servers, page caching, and checkout checks (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-1', 'lesson-audio-itops-b1-03', 'owner', 0, 6.7, 'Hey, our marketing team just sent out a flash sale email and website traffic doubled.', '[Ops Lead] Ê bạn ơi, team marketing vừa gửi email flash sale nên lượng truy cập web tăng gấp đôi rồi.', 'flash sale, traffic doubled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-2', 'lesson-audio-itops-b1-03', 'owner', 6.7, 14.2, 'I saw the live chart jump a minute ago; how are the web servers handling the load?', '[Cloud Eng] Nãy mình cũng vừa thấy biểu đồ nhảy vọt; dàn web server chịu tải ổn không?', 'live chart, handling the load', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-3', 'lesson-audio-itops-b1-03', 'owner', 14.2, 20.9, 'Average CPU across the web servers is around seventy five percent, and pages feel slower.', '[Ops Lead] CPU trung bình trên các web server đang tầm 75%, mở trang bắt đầu thấy hơi chậm rồi.', 'average CPU, slower', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-4', 'lesson-audio-itops-b1-03', 'owner', 20.9, 26.8, 'Did automatic scaling start adding extra server instances when CPU crossed seventy percent?', '[Cloud Eng] Hệ thống auto-scaling có tự bật thêm server khi CPU vượt 70% không?', 'automatic scaling, extra server', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-5', 'lesson-audio-itops-b1-03', 'owner', 26.8, 34.3, 'It added two servers, but the maximum limit was set to six servers in our scaling rule.', '[Ops Lead] Nó thêm được hai máy rồi, nhưng giới hạn tối đa trong cấu hình chỉ đang để là 6 server thôi.', 'maximum limit, scaling rule', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-6', 'lesson-audio-itops-b1-03', 'owner', 34.3, 42.3, 'Let us raise that limit to ten servers right now so the system has plenty of extra space.', '[Cloud Eng] Nâng giới hạn đó lên 10 server ngay đi để hệ thống còn dư sức chịu tải.', 'raise that limit, extra space', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-7', 'lesson-audio-itops-b1-03', 'owner', 42.3, 49.4, 'How long does each new web server take to start up and pass its health check?', '[Ops Lead] Mỗi web server mới bật lên rồi qua bước health check mất khoảng bao lâu?', 'start up, health check', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-8', 'lesson-audio-itops-b1-03', 'owner', 49.4, 56.1, 'About ninety seconds; two more servers are already starting and should join the balancer soon.', '[Cloud Eng] Tầm 90 giây thôi; hai server nữa đang khởi động rồi, lát nữa sẽ tự nối vào load balancer.', 'ninety seconds, join the balancer', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-9', 'lesson-audio-itops-b1-03', 'owner', 56.1, 62.8, 'What about the main database? Are heavy product searches putting too much pressure on it?', '[Ops Lead] Còn database chính thì sao? Khách tìm kiếm sản phẩm nhiều có làm nó quá tải không?', 'product searches, pressure', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-10', 'lesson-audio-itops-b1-03', 'owner', 62.8, 70.8, 'Database reads went up fast, so turning on longer page caching for product lists will help right away.', '[Cloud Eng] Lượt đọc database tăng nhanh lắm, mình kéo dài thời gian cache cho trang danh sách sản phẩm sẽ đỡ tải ngay.', 'went up fast, page caching', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-11', 'lesson-audio-itops-b1-03', 'owner', 70.8, 77.5, 'Make sure we do not cache personal cart pages or payment checkout screens by mistake.', '[Ops Lead] Nhớ kiểm tra kỹ kẻo cache nhầm trang giỏ hàng cá nhân hay màn hình thanh toán nhé.', 'by mistake, checkout screens', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-12', 'lesson-audio-itops-b1-03', 'owner', 77.5, 83.8, 'Of course, caching only applies to public product pages, images, and static banner files.', '[Cloud Eng] Yên tâm, cache chỉ áp dụng cho trang sản phẩm công khai, hình ảnh với các file banner tĩnh thôi.', 'product pages, static files', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-13', 'lesson-audio-itops-b1-03', 'owner', 83.8, 90.9, 'The new cache rule is live, and database read traffic just dropped by nearly forty percent.', '[Cloud Eng] Cấu hình cache mới chạy rồi, lượng truy vấn đọc database vừa giảm gần 40% luôn.', 'cache rule, dropped by nearly', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-14', 'lesson-audio-itops-b1-03', 'owner', 90.9, 98, 'Awesome, and all eight web servers are now green with average CPU back under fifty percent.', '[Ops Lead] Ngon quá, cả 8 web server đều xanh rồi, CPU trung bình cũng hạ xuống dưới 50%.', 'average CPU, under fifty percent', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-15', 'lesson-audio-itops-b1-03', 'owner', 98, 106, 'I also ran a quick test order on the checkout page and it finished in under one second.', '[Cloud Eng] Mình cũng vừa đặt thử một đơn trên trang thanh toán, xử lý xong chưa tới 1 giây.', 'test order, finished', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-16', 'lesson-audio-itops-b1-03', 'owner', 106, 112.3, 'Let us ask marketing to tell operations one day ahead before future flash sales.', '[Ops Lead] Nhắn bên marketing lần sau có flash sale thì báo trước cho bên vận hành một ngày nhé.', 'one day ahead, future', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-17', 'lesson-audio-itops-b1-03', 'owner', 112.3, 118.6, 'Good idea; that way we can prepare the servers and check our limits early.', '[Cloud Eng] Chuẩn đấy; như vậy mình chủ động chuẩn bị server và kiểm tra hạn mức từ sớm.', 'prepare the servers, check our limits', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-18', 'lesson-audio-itops-b1-03', 'owner', 118.6, 125.7, 'I will stay on the live dashboard until the sale ends and reduce the servers tonight.', '[Cloud Eng] Mình sẽ canh dashboard trực tiếp tới hết đợt sale, rồi tối nay giảm bớt server lại.', 'live dashboard, reduce', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-04', 'owner', 'audio-itops-b1-04', 'B1 | 04. Resolving Email Delivery Delays & Queue Backlog (IT Ops)', 'A 2-minute B1 mail operations call fixing delayed customer emails, checking a stuck mail queue, stopping a noisy loop, and clearing deliveries (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-1', 'lesson-audio-itops-b1-04', 'owner', 0, 6.3, 'Hi, several customers called support because their order confirmation emails still have not arrived.', '[Helpdesk] Chào bạn, nãy giờ mấy khách hàng gọi lên báo vẫn chưa nhận được email xác nhận đơn hàng.', 'order confirmation, arrived', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-2', 'lesson-audio-itops-b1-04', 'owner', 6.3, 13.4, 'Are those emails bouncing back with errors, or are they simply arriving much later than usual?', '[Mail Admin] Mấy email đó bị trả ngược báo lỗi, hay chỉ đến chậm hơn bình thường nhiều thôi?', 'bouncing back, later than usual', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-3', 'lesson-audio-itops-b1-04', 'owner', 13.4, 20.1, 'They are arriving about forty minutes late, and staff noticed internal messages are delayed too.', '[Helpdesk] Đến trễ tầm 40 phút lận, mà nhân viên trong công ty cũng thấy thông báo nội bộ bị chậm theo.', 'delayed, internal messages', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-4', 'lesson-audio-itops-b1-04', 'owner', 20.1, 27.6, 'Let me check our outgoing mail server; wow, there are twelve thousand messages stuck in the queue.', '[Mail Admin] Để mình kiểm tra server gửi mail; trời ơi, đang có tới 12.000 email bị kẹt trong hàng đợi.', 'outgoing mail server, stuck in the queue', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-5', 'lesson-audio-itops-b1-04', 'owner', 27.6, 33.5, 'Twelve thousand? Normally our busy morning queue only holds around two hundred emails.', '[Helpdesk] 12.000 cái luôn hả? Bình thường buổi sáng cao điểm hàng đợi cũng chỉ tầm 200 email thôi mà.', 'normally, holds around', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-6', 'lesson-audio-itops-b1-04', 'owner', 33.5, 40.2, 'Wait a second, most of these messages are coming from one single automatic reporting account.', '[Mail Admin] Khoan đã, gần hết đống thư này đều gửi ra từ đúng một tài khoản báo cáo tự động.', 'automatic reporting account', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-7', 'lesson-audio-itops-b1-04', 'owner', 40.2, 47.3, 'What is that account sending? It looks like the same five megabyte attachment repeated every second.', '[Mail Admin] Tài khoản đó đang gửi gì vậy? Nhìn như cùng một file đính kèm 5 MB mà gửi lặp lại mỗi giây luôn.', 'attachment, repeated', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-8', 'lesson-audio-itops-b1-04', 'owner', 47.3, 54.4, 'Oh no, a scheduled billing script must be stuck in a retry loop after failing once.', '[Helpdesk] Thôi rồi, chắc script xuất hóa đơn định kỳ bị kẹt vòng lặp gửi lại sau khi lỗi một lần rồi.', 'scheduled script, retry loop', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-9', 'lesson-audio-itops-b1-04', 'owner', 54.4, 60.7, 'Exactly; it filled up all outgoing mail workers, blocking real customer emails behind it.', '[Mail Admin] Chuẩn luôn; nó chiếm kín hết luồng gửi thư đi, làm nghẽn toàn bộ email khách hàng thật ở phía sau.', 'mail workers, blocking', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-10', 'lesson-audio-itops-b1-04', 'owner', 60.7, 67.8, 'First, I am pausing that automatic sender account so no new copy messages enter the queue.', '[Mail Admin] Trước mắt mình tạm khóa tài khoản gửi tự động đó để không đẩy thêm thư trùng vào hàng đợi nữa.', 'pausing, copy messages', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-11', 'lesson-audio-itops-b1-04', 'owner', 67.8, 74.1, 'Can we clear out only those repeated report messages without deleting real customer emails?', '[Helpdesk] Mình dọn riêng mấy thư báo cáo bị lặp đó mà không xóa nhầm email khách hàng thật được không?', 'clear out, without deleting', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-12', 'lesson-audio-itops-b1-04', 'owner', 74.1, 81.2, 'Yes, I can filter the queue by sender address and remove only the stuck reporting job.', '[Mail Admin] Được chứ, mình lọc hàng đợi theo địa chỉ người gửi rồi xóa riêng tác vụ báo cáo bị kẹt thôi.', 'filter the queue, sender address', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-13', 'lesson-audio-itops-b1-04', 'owner', 81.2, 87.5, 'Done, eleven thousand repeated messages are cleared, leaving only three hundred real customer emails.', '[Mail Admin] Xong rồi, mình dọn sạch 11.000 thư lặp, giờ chỉ còn 300 email khách hàng thật thôi.', 'real customer emails', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-14', 'lesson-audio-itops-b1-04', 'owner', 87.5, 94.6, 'Now I am pushing the mail queue so the server sends those waiting confirmations right away.', '[Mail Admin] Giờ mình cho xả hàng đợi để server gửi ngay mấy thư xác nhận đang chờ.', 'pushing the mail queue, right away', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-15', 'lesson-audio-itops-b1-04', 'owner', 94.6, 101.7, 'I just tested a password reset email and it arrived in my inbox within three seconds.', '[Helpdesk] Mình vừa thử gửi một email đặt lại mật khẩu, 3 giây là tới hộp thư đến rồi.', 'arrived in my inbox', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-16', 'lesson-audio-itops-b1-04', 'owner', 101.7, 109.7, 'Great news; I will also tell the billing team to add a clear retry limit on their script.', '[Mail Admin] Tốt quá; để mình nhắn thêm team thanh toán đặt giới hạn số lần thử lại cho script của họ.', 'clear retry limit', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-17', 'lesson-audio-itops-b1-04', 'owner', 109.7, 118.1, 'Should we set a queue size alert so operations gets a message if more than five hundred emails wait?', '[Helpdesk] Mình đặt thêm cảnh báo hàng đợi để nếu có hơn 500 email chờ là bên vận hành nhận tin báo ngay nhé?', 'queue size alert', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-18', 'lesson-audio-itops-b1-04', 'owner', 118.1, 125.2, 'Yes, I am adding that monitoring rule right now along with a per minute sending limit.', '[Mail Admin] Ừ, mình đang thêm luật giám sát đó ngay đây, kèm luôn giới hạn số thư gửi mỗi phút.', 'monitoring rule, sending limit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-05', 'owner', 'audio-itops-b1-05', 'B1 | 05. Cleaning Up Inodes & Stuck Background Jobs (IT Ops)', 'A 2-minute B1 Linux operations conversation solving a "no space left" error caused by 100% inode usage from tiny session files (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-1', 'lesson-audio-itops-b1-05', 'owner', 0, 8, 'Hi, I am confused because the web server says no space left, even though disk space looks fine.', '[Junior Ops] Chào bạn, mình hơi khó hiểu vì web server báo hết ổ đĩa dù dung lượng trống vẫn còn nhiều.', 'confused, no space left', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-2', 'lesson-audio-itops-b1-05', 'owner', 8, 14.3, 'How much free space did the normal disk command show when you checked it?', '[Linux Eng] Lúc bạn chạy lệnh kiểm tra ổ đĩa bình thường thì thấy còn trống bao nhiêu?', 'disk command, free space', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-3', 'lesson-audio-itops-b1-05', 'owner', 14.3, 21.8, 'It showed thirty five percent free, about forty gigabytes available, yet nothing can create a new file.', '[Junior Ops] Còn trống tới 35%, khoảng 40 GB lận, vậy mà không chương trình nào tạo file mới được.', 'available, create a new file', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-4', 'lesson-audio-itops-b1-05', 'owner', 21.8, 28.5, 'Aha, that is a common Linux problem; please check the inode usage table right now.', '[Linux Eng] À, lỗi này trên Linux hay gặp lắm; bạn kiểm tra ngay bảng dung lượng inode đi.', 'common problem, inode usage', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-5', 'lesson-audio-itops-b1-05', 'owner', 28.5, 34.4, 'Oh wow, inode usage on the root drive is at one hundred percent.', '[Junior Ops] Ôi trời, mức dùng inode trên phân vùng gốc chạm đúng 100% luôn rồi.', 'root drive, one hundred percent', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-6', 'lesson-audio-itops-b1-05', 'owner', 34.4, 41.5, 'Could you quickly explain why a drive runs out of inodes while gigabytes are still free?', '[Junior Ops] Bạn giải thích nhanh giúp mình sao ổ đĩa lại hết inode trong khi vẫn còn dư mấy chục GB được không?', 'quickly explain, runs out of', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-7', 'lesson-audio-itops-b1-05', 'owner', 41.5, 49, 'Every single file needs one inode record, so millions of tiny files can use up every slot.', '[Linux Eng] Mỗi file dù nhỏ xíu cũng tốn một mục inode, nên hàng triệu file nhỏ sẽ ngốn sạch hết số lượng inode.', 'inode record, tiny files, use up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-8', 'lesson-audio-itops-b1-05', 'owner', 49, 55.7, 'Let us find which folder holds the highest number of small files on this machine.', '[Linux Eng] Giờ tìm xem thư mục nào trên máy này đang chứa nhiều file nhỏ nhất nhé.', 'folder, highest number', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-9', 'lesson-audio-itops-b1-05', 'owner', 55.7, 62.8, 'Found it; the temporary session folder has over two million tiny files created over three months.', '[Junior Ops] Thấy rồi; thư mục lưu session tạm có hơn 2 triệu file nhỏ dồn từ 3 tháng nay.', 'session folder, two million', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-10', 'lesson-audio-itops-b1-05', 'owner', 62.8, 69.1, 'Why did our nightly cleanup job stop clearing old session files three months ago?', '[Linux Eng] Sao tác vụ dọn dẹp hằng đêm lại ngừng xóa mấy file session cũ từ 3 tháng trước vậy?', 'nightly cleanup job', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-11', 'lesson-audio-itops-b1-05', 'owner', 69.1, 76.6, 'Let me check the scheduled task file; someone turned off the cleanup line during testing and forgot.', '[Junior Ops] Để mình xem file lịch chạy tự động; có ai tắt dòng dọn dẹp lúc test rồi quên bật lại mất.', 'scheduled task, turned off, forgot', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-12', 'lesson-audio-itops-b1-05', 'owner', 76.6, 84.1, 'Good catch; remember not to run a simple delete all command on two million files at once.', '[Linux Eng] Phát hiện chuẩn đấy; nhớ đừng chạy lệnh xóa hết thông thường một lúc trên 2 triệu file nhé.', 'good catch, at once', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-13', 'lesson-audio-itops-b1-05', 'owner', 84.1, 90, 'Right, because the shell command will fail with a too many files error.', '[Junior Ops] Đúng rồi, chạy vậy lệnh shell sẽ báo lỗi quá nhiều file ngay.', 'shell command, too many files', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-14', 'lesson-audio-itops-b1-05', 'owner', 90, 98.8, 'Use the find command to delete in small groups for files older than two days so active sessions stay safe.', '[Linux Eng] Dùng lệnh find để xóa dần từng nhóm các file cũ hơn hai ngày, như vậy không ảnh hưởng các phiên đang hoạt động.', 'small groups, older than, stay safe', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-15', 'lesson-audio-itops-b1-05', 'owner', 98.8, 106.3, 'It is running smoothly now, and inode usage already dropped from one hundred down to twenty percent.', '[Junior Ops] Lệnh đang chạy êm rồi, mức dùng inode vừa tụt từ 100% xuống còn 20%.', 'running smoothly, dropped', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-16', 'lesson-audio-itops-b1-05', 'owner', 106.3, 113.8, 'Next, turn the nightly cleanup schedule back on and check that the web app writes logs cleanly.', '[Linux Eng] Xong rồi bật lại lịch dọn dẹp hằng đêm và kiểm tra xem web app ghi log lại bình thường chưa nhé.', 'turn back on, writes logs', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-17', 'lesson-audio-itops-b1-05', 'owner', 113.8, 121.8, 'Application logs are writing again, and I added an inode alert at eighty percent to our monitoring tool.', '[Junior Ops] Log ứng dụng ghi lại bình thường rồi, mình cũng thêm cảnh báo inode ở mức 80% trên hệ thống giám sát.', 'inode alert, monitoring tool', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-18', 'lesson-audio-itops-b1-05', 'owner', 121.8, 128.5, 'Nice work today; checking inodes is a very useful habit every Linux engineer should know.', '[Linux Eng] Làm tốt lắm; kiểm tra inode là thói quen cực kỳ hữu ích mà kỹ sư Linux nào cũng nên nắm.', 'useful habit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-06', 'owner', 'audio-itops-b1-06', 'B1 | 06. Planning a Safe Database Migration Weekend (IT Ops)', 'A 2-minute B1 planning conversation preparing a customer database move to a larger server with test runs, checks, and a backup plan (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-1', 'lesson-audio-itops-b1-06', 'owner', 0, 5.5, 'Good afternoon, let us finish our checklist for Saturday’s customer database migration.', '[Project Lead] Chào buổi chiều, mình chốt lại checklist cho đợt chuyển database khách hàng tối thứ Bảy này nhé.', 'checklist, database migration', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-2', 'lesson-audio-itops-b1-06', 'owner', 5.5, 12.6, 'Sure, our current server is almost full, so moving to the new machine is very important.', '[DBA] Ok, server hiện tại cũng sắp đầy rồi nên chuyển sang máy mới là rất cần thiết.', 'almost full, very important', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-3', 'lesson-audio-itops-b1-06', 'owner', 12.6, 18.5, 'How much total downtime should we tell customers to expect on Saturday night?', '[Project Lead] Tối thứ Bảy mình nên báo khách hàng thời gian tạm ngưng dự kiến là bao lâu?', 'downtime, expect', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-4', 'lesson-audio-itops-b1-06', 'owner', 18.5, 26.5, 'In our test run on staging yesterday, the final switch took twenty five minutes from start to finish.', '[DBA] Hôm qua chạy thử trên staging thì bước chuyển cuối cùng mất 25 phút từ đầu tới cuối.', 'test run, final switch', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-5', 'lesson-audio-itops-b1-06', 'owner', 26.5, 33.2, 'Let us share a one hour maintenance window so we have plenty of extra time.', '[Project Lead] Vậy mình thông báo lịch bảo trì 1 tiếng đi cho dư dả thời gian dự phòng.', 'maintenance window, extra time', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-6', 'lesson-audio-itops-b1-06', 'owner', 33.2, 39.9, 'How are we copying such a large database without keeping the website offline for hours?', '[Project Lead] Database lớn như vậy mình chuyển kiểu gì để web không bị ngưng hoạt động hàng giờ?', 'copying, offline for hours', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-7', 'lesson-audio-itops-b1-06', 'owner', 39.9, 47, 'We already set up live syncing, so the new server gets every change in real time.', '[DBA] Bên mình cài đồng bộ trực tiếp rồi, nên mọi thay đổi đều tự cập nhật sang server mới theo thời gian thực.', 'live syncing, real time', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-8', 'lesson-audio-itops-b1-06', 'owner', 47, 55.4, 'That means during maintenance we only pause writes briefly and wait for the last few rows to catch up.', '[DBA] Tức là lúc bảo trì mình chỉ tạm dừng ghi dữ liệu một chút rồi đợi vài dòng cuối đồng bộ xong là được.', 'pause writes, catch up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-9', 'lesson-audio-itops-b1-06', 'owner', 55.4, 62.5, 'Once the data matches completely, how will we check that nothing was missed during the move?', '[Project Lead] Khi dữ liệu khớp rồi thì kiểm tra kiểu gì để chắc chắn không sót dữ liệu nào?', 'matches completely, missed', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-10', 'lesson-audio-itops-b1-06', 'owner', 62.5, 70, 'I wrote a check script that compares table row counts and data checks across all main tables.', '[DBA] Mình viết sẵn script đối chiếu số dòng và kiểm tra toàn vẹn dữ liệu trên tất cả các bảng chính rồi.', 'check script, row counts', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-11', 'lesson-audio-itops-b1-06', 'owner', 70, 77.1, 'And what happens if our application servers show unexpected errors right after using the new database?', '[Project Lead] Còn lỡ các server ứng dụng báo lỗi bất ngờ ngay sau khi trỏ sang database mới thì xử lý sao?', 'unexpected errors', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-12', 'lesson-audio-itops-b1-06', 'owner', 77.1, 84.2, 'We will keep the old database server safe and online in read only mode all weekend.', '[DBA] Mình vẫn giữ nguyên server database cũ ở chế độ chỉ đọc suốt cuối tuần.', 'read only mode', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-13', 'lesson-audio-itops-b1-06', 'owner', 84.2, 92.2, 'If any important quick test fails within fifteen minutes, we simply point traffic back to the old server.', '[DBA] Nếu trong 15 phút đầu có bài test nhanh quan trọng nào bị lỗi thì mình trỏ hệ thống quay lại server cũ ngay.', 'quick test, point traffic back', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-14', 'lesson-audio-itops-b1-06', 'owner', 92.2, 99.7, 'Have we checked firewall rules and login passwords so every app server can reach the new host?', '[Project Lead] Mình đã kiểm tra luật firewall với mật khẩu đăng nhập để tất cả app server kết nối được máy mới chưa?', 'login passwords, reach the new host', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-15', 'lesson-audio-itops-b1-06', 'owner', 99.7, 106, 'Yes, we tested network access and login permissions from every production server earlier today.', '[DBA] Rồi đó, sáng nay bên mình đã test kết nối mạng và quyền đăng nhập từ từng server production luôn.', 'network access, login permissions', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-16', 'lesson-audio-itops-b1-06', 'owner', 106, 111.9, 'Also remember to take a fresh full backup right before pausing production writes.', '[Project Lead] Nhớ tạo thêm một bản backup đầy đủ mới ngay trước khi tạm dừng ghi trên production nhé.', 'fresh full backup', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-17', 'lesson-audio-itops-b1-06', 'owner', 111.9, 119, 'It is step two on our guide, and two engineers will double check every command together.', '[DBA] Bước đó nằm ngay mục số 2 trong tài liệu hướng dẫn rồi, và sẽ có hai kỹ sư cùng kiểm tra chéo từng câu lệnh.', 'guide, double check', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-18', 'lesson-audio-itops-b1-06', 'owner', 119, 126.5, 'Everything looks well prepared; let us meet on the team call at ten forty five Saturday night.', '[Project Lead] Mọi thứ chuẩn bị rất kỹ rồi; hẹn gặp nhau trong cuộc gọi nhóm lúc 10 giờ 45 tối thứ Bảy nhé.', 'well prepared, team call', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-07', 'owner', 'audio-itops-b1-07', 'B1 | 07. Responding to a Phishing Email & Account Check (IT Ops)', 'A 2-minute B1 security operations phone call helping an employee who clicked a fake invoice link, signing out sessions, blocking the site, and turning on two-factor login (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-1', 'lesson-audio-itops-b1-07', 'owner', 0, 8.4, 'Hello security desk, I think I just made a mistake and clicked a strange invoice link in my email.', '[Staff] Alo bộ phận bảo mật ạ, mình lỡ tay bấm vào một đường link hóa đơn lạ trong email rồi.', 'made a mistake, strange invoice link', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-2', 'lesson-audio-itops-b1-07', 'owner', 8.4, 15.5, 'Thank you for calling right away; reporting it fast is the best thing you could do.', '[Security Ops] Cảm ơn bạn đã gọi báo ngay nhé; báo càng sớm thì xử lý càng an toàn.', 'reporting it fast', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-3', 'lesson-audio-itops-b1-07', 'owner', 15.5, 23.5, 'Tell me calmly what happened after you clicked the link; did a login page ask for your password?', '[Security Ops] Bạn cứ bình tĩnh kể lại giúp mình sau khi bấm link thì hiện ra gì; có trang đăng nhập nào đòi mật khẩu không?', 'calmly, login page', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-4', 'lesson-audio-itops-b1-07', 'owner', 23.5, 32.7, 'Yes, it looked just like our company portal, so I typed my work email and password before seeing the strange address.', '[Staff] Có, trang đó nhìn giống hệt cổng nội bộ công ty nên mình lỡ nhập email với mật khẩu xong mới để ý tên miền lạ.', 'company portal, strange address', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-5', 'lesson-audio-itops-b1-07', 'owner', 32.7, 39.8, 'Okay, do not worry; let me check your account login history and active sessions right now.', '[Security Ops] Ok đừng lo quá nhé; để mình kiểm tra lịch sử đăng nhập và các phiên đang hoạt động của bạn ngay.', 'login history, active sessions', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-6', 'lesson-audio-itops-b1-07', 'owner', 39.8, 48.6, 'I see a login attempt from an unknown city two minutes ago, so we need to lock it down fast.', '[Security Ops] Mình thấy có lượt đăng nhập từ một thành phố lạ cách đây 2 phút, cần khóa ngay lập tức.', 'unknown city, lock it down', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-7', 'lesson-audio-itops-b1-07', 'owner', 48.6, 56.1, 'First, I am signing out all active sessions on every device and resetting your password right now.', '[Security Ops] Trước tiên mình đăng xuất toàn bộ thiết bị đang đăng nhập và đặt lại mật khẩu cho bạn ngay bây giờ.', 'signing out, active sessions', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-8', 'lesson-audio-itops-b1-07', 'owner', 56.1, 62, 'Did the attacker open any shared files or forward emails from my mailbox?', '[Staff] Kẻ gian có kịp mở file dùng chung nào hay chuyển tiếp email từ hộp thư của mình không?', 'attacker, forward emails, mailbox', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-9', 'lesson-audio-itops-b1-07', 'owner', 62, 69.1, 'Good news, the activity log shows zero file downloads and no hidden forwarding rules were added.', '[Security Ops] Tin vui là log hoạt động không thấy tải file nào, cũng chưa có luật tự chuyển tiếp thư ẩn nào bị thêm vào.', 'activity log, forwarding rules', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-10', 'lesson-audio-itops-b1-07', 'owner', 69.1, 75.4, 'I am so glad; did the website download any strange file onto my laptop?', '[Staff] May quá; trang web đó có tự tải file lạ nào về laptop của mình không?', 'glad, strange file', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-11', 'lesson-audio-itops-b1-07', 'owner', 75.4, 82.5, 'Our antivirus scan shows your laptop is clean, though I will run one more quick check.', '[Security Ops] Phần mềm diệt virus báo máy bạn vẫn sạch, nhưng mình sẽ cho quét nhanh thêm một lượt nữa cho chắc.', 'antivirus scan, quick check', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-12', 'lesson-audio-itops-b1-07', 'owner', 82.5, 90.9, 'Please forward the fake email to our security inbox so we can block that website for the whole company.', '[Security Ops] Bạn chuyển tiếp email giả đó sang hộp thư bảo mật giúp mình để bên mình chặn trang đó trên toàn công ty nhé.', 'fake email, whole company', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-13', 'lesson-audio-itops-b1-07', 'owner', 90.9, 98.9, 'I am forwarding it now; do I also need to change my password on any other work apps?', '[Staff] Mình đang chuyển tiếp đây; mình có cần đổi mật khẩu trên ứng dụng công việc nào khác không?', 'change my password', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-14', 'lesson-audio-itops-b1-07', 'owner', 98.9, 106.9, 'Only if you used the same password anywhere else; always keep your work password different from other accounts.', '[Security Ops] Chỉ cần đổi nếu bạn dùng trùng mật khẩu đó ở chỗ khác thôi; nhớ luôn đặt mật khẩu công việc riêng biệt nhé.', 'same password, different', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-15', 'lesson-audio-itops-b1-07', 'owner', 106.9, 115.3, 'Next, let us turn on two factor login on your phone so a stolen password alone cannot sign in.', '[Security Ops] Tiếp theo mình bật đăng nhập hai bước trên điện thoại để lỡ có lộ mật khẩu cũng không ai vào được.', 'two factor login, stolen password', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-16', 'lesson-audio-itops-b1-07', 'owner', 115.3, 122.8, 'I just scanned the setup code in my phone app and typed in the six digit code.', '[Staff] Mình vừa quét mã trên ứng dụng điện thoại rồi nhập mã 6 chữ số xong rồi.', 'setup code, six digit code', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-17', 'lesson-audio-itops-b1-07', 'owner', 122.8, 131.2, 'Your account is safe again, and I have already blocked the sender and removed the email from other inboxes.', '[Security Ops] Tài khoản bạn an toàn lại rồi đấy, mình cũng đã chặn người gửi và gỡ email đó khỏi hộp thư của mọi người.', 'blocked the sender, removed', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-18', 'lesson-audio-itops-b1-07', 'owner', 131.2, 138.7, 'Thanks so much for your help; I will always check the sender address carefully from now on.', '[Staff] Cảm ơn bạn hỗ trợ nhiều nhé; từ giờ mình sẽ luôn xem kỹ địa chỉ người gửi trước khi bấm.', 'sender address, carefully', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-08', 'owner', 'audio-itops-b1-08', 'B1 | 08. Fixing Broken Scheduled Backups & Storage Alerts (IT Ops)', 'A 2-minute B1 operations call fixing three failed overnight backup jobs, expired cloud storage keys, manual upload, and restore tests (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-1', 'lesson-audio-itops-b1-08', 'owner', 0, 8.4, 'Good morning, I saw on the daily report that our file server backup failed three nights in a row.', '[Shift Operator] Chào buổi sáng, mình xem báo cáo hằng ngày thấy backup của file server bị lỗi ba đêm liên tiếp rồi.', 'daily report, three nights in a row', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-2', 'lesson-audio-itops-b1-08', 'owner', 8.4, 15.9, 'Three nights? Why did the monitoring board only show a yellow warning instead of a red alert?', '[Backup Eng] Ba đêm liền á? Sao màn hình giám sát chỉ hiện cảnh báo vàng chứ không báo đỏ vậy?', 'monitoring board, instead of', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-3', 'lesson-audio-itops-b1-08', 'owner', 15.9, 23.9, 'The alert rule only turns red after five failures, which feels much too late for important company files.', '[Shift Operator] Luật cảnh báo đang để lỗi 5 lần mới báo đỏ, như vậy trễ quá với dữ liệu quan trọng của công ty.', 'too late, company files', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-4', 'lesson-audio-itops-b1-08', 'owner', 23.9, 31.9, 'You are completely right; let us fix the broken backup first and change that alert rule right after.', '[Backup Eng] Đúng thật; mình sửa xong backup bị lỗi trước rồi chỉnh lại luật cảnh báo ngay sau đó nhé.', 'broken backup, alert rule', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-5', 'lesson-audio-itops-b1-08', 'owner', 31.9, 40.3, 'I opened last night’s backup log, and the job failed right at the start with an access denied message.', '[Shift Operator] Mình mở log backup đêm qua thì thấy vừa chạy đã lỗi ngay với thông báo bị từ chối truy cập.', 'access denied', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-6', 'lesson-audio-itops-b1-08', 'owner', 40.3, 46.6, 'Access denied usually means our cloud storage key expired or someone changed folder permissions.', '[Backup Eng] Báo từ chối truy cập thì thường là khóa lưu trữ cloud hết hạn hoặc có ai đổi quyền thư mục rồi.', 'cloud storage key, permissions', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-7', 'lesson-audio-itops-b1-08', 'owner', 46.6, 53.7, 'Let me check the service account page; yes, the backup access key expired on Monday evening.', '[Backup Eng] Để mình xem trang tài khoản dịch vụ; đúng rồi, khóa backup vừa hết hạn tối thứ Hai.', 'service account, access key', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-8', 'lesson-audio-itops-b1-08', 'owner', 53.7, 61.2, 'Are all our local backup copies from the past week still safe on the office storage server?', '[Shift Operator] Mấy bản backup nội bộ tuần qua trên server lưu trữ ở văn phòng vẫn ổn hết chứ?', 'local backup copies, storage server', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-9', 'lesson-audio-itops-b1-08', 'owner', 61.2, 68.3, 'Yes, local backups worked fine; only the cloud backup upload failed because of the expired key.', '[Backup Eng] Ừ, backup nội bộ vẫn chạy ngon; chỉ có bước đẩy lên cloud bị lỗi do khóa hết hạn thôi.', 'cloud backup upload', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-10', 'lesson-audio-itops-b1-08', 'owner', 68.3, 75.8, 'I am creating a new service key now and updating the saved key inside our backup tool.', '[Backup Eng] Mình đang tạo khóa mới rồi cập nhật lại vào trong công cụ backup đây.', 'saved key, backup tool', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-11', 'lesson-audio-itops-b1-08', 'owner', 75.8, 83.3, 'Should we wait until midnight to see if it works, or run a manual backup right now?', '[Shift Operator] Mình đợi tới nửa đêm xem có chạy không, hay chạy backup thủ công ngay bây giờ luôn?', 'manual backup', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-12', 'lesson-audio-itops-b1-08', 'owner', 83.3, 91.3, 'Never wait until midnight after three failures; let us start a quick upload of new files right away.', '[Backup Eng] Lỗi ba hôm rồi thì đừng đợi nửa đêm; mình chạy đồng bộ nhanh các file mới lên ngay đi.', 'quick upload, right away', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-13', 'lesson-audio-itops-b1-08', 'owner', 91.3, 97.2, 'The upload started cleanly and is sending files at forty megabytes per second.', '[Shift Operator] Quá trình tải lên chạy êm rồi, tốc độ đang đạt 40 MB mỗi giây.', 'sending files, per second', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-14', 'lesson-audio-itops-b1-08', 'owner', 97.2, 102.7, 'Since it only uploads changed files, it should finish within five minutes.', '[Backup Eng] Vì chỉ đẩy những file có thay đổi nên chắc tầm 5 phút là xong thôi.', 'changed files, within five minutes', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-15', 'lesson-audio-itops-b1-08', 'owner', 102.7, 110.7, 'It just finished with zero errors! Let us also restore one test folder to staging to be sure.', '[Shift Operator] Chạy xong không một lỗi nào luôn! Mình khôi phục thử một thư mục lên staging kiểm tra cho chắc nhé.', 'to be sure, staging', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-16', 'lesson-audio-itops-b1-08', 'owner', 110.7, 115.7, 'The test restore worked and every document opened with no errors.', '[Backup Eng] Khôi phục thử thành công rồi, mở tài liệu nào cũng lên bình thường không lỗi.', 'test restore, no errors', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-17', 'lesson-audio-itops-b1-08', 'owner', 115.7, 124.5, 'Now I am updating the alert rule so even a single missed backup sends a red ticket the next morning.', '[Backup Eng] Giờ mình chỉnh lại luật cảnh báo để chỉ cần lỗi một lần là sáng hôm sau tự tạo ticket khẩn cấp ngay.', 'alert rule, missed backup', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-18', 'lesson-audio-itops-b1-08', 'owner', 124.5, 133.3, 'Thanks a lot, I will add a calendar reminder to change the storage key before it expires in three months.', '[Shift Operator] Cảm ơn nhiều nhé, để mình đặt lịch nhắc đổi khóa lưu trữ trước khi hết hạn trong ba tháng tới.', 'calendar reminder, in three months', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-09', 'owner', 'audio-itops-b1-09', 'B1 | 09. Troubleshooting Slow API Calls & Timeout Errors (IT Ops)', 'A 2-minute B1 incident call tracing mobile app timeouts through API gateway logs to a slow payment partner and switching to a backup service (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-1', 'lesson-audio-itops-b1-09', 'owner', 0, 6.7, 'Hi, mobile app users are reporting loading spinners and timeout errors when paying for orders.', '[App Support] Chào bạn, người dùng app di động đang báo màn hình cứ xoay mãi rồi bị lỗi timeout lúc thanh toán đơn hàng.', 'loading spinners, timeout errors', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-2', 'lesson-audio-itops-b1-09', 'owner', 6.7, 15.5, 'Let me open the API gateway dashboard; yes, the error rate on the payment endpoint just rose to twelve percent.', '[SRE] Để mình mở dashboard API gateway xem; đúng rồi, tỷ lệ lỗi ở API thanh toán vừa tăng lên 12%.', 'API gateway, error rate, endpoint', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-3', 'lesson-audio-itops-b1-09', 'owner', 15.5, 21.8, 'Are other mobile features like browsing products or viewing order history still working fast?', '[SRE] Các tính năng khác trên app như xem sản phẩm hay lịch sử đơn hàng vẫn chạy nhanh chứ?', 'order history, browsing products', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-4', 'lesson-audio-itops-b1-09', 'owner', 21.8, 28.9, 'Yes, everything else responds in under half a second; only the checkout payment call is hanging.', '[App Support] Ừ, mấy chỗ khác phản hồi chưa tới nửa giây; chỉ riêng bước gọi thanh toán là bị treo thôi.', 'responds, hanging', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-5', 'lesson-audio-itops-b1-09', 'owner', 28.9, 37.7, 'Let us check the request logs to see whether the delay is inside our own code or an outside partner.', '[SRE] Mình xem log request để biết độ trễ nằm ở code bên mình hay do phía đối tác bên ngoài nhé.', 'request logs, outside partner', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-6', 'lesson-audio-itops-b1-09', 'owner', 37.7, 46.5, 'Look at the time details: our internal service finishes in twenty milliseconds, then waits thirty seconds for the bank API.', '[SRE] Nhìn chi tiết thời gian này: hệ thống bên mình xử lý xong trong 20 mili giây, xong phải đợi tới 30 giây từ API ngân hàng.', 'time details, internal service', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-7', 'lesson-audio-itops-b1-09', 'owner', 46.5, 53.2, 'Thirty seconds is way too long! Let me check the payment partner’s public status page.', '[App Support] 30 giây thì lâu quá rồi! Để mình mở trang trạng thái của đối tác thanh toán kiểm tra xem.', 'payment partner, public status page', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-8', 'lesson-audio-itops-b1-09', 'owner', 53.2, 59.5, 'They just posted an incident notice saying their European payment gateway is running slowly.', '[App Support] Họ vừa đăng thông báo sự cố là cổng thanh toán khu vực châu Âu của họ đang bị chậm.', 'incident notice, running slowly', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-9', 'lesson-audio-itops-b1-09', 'owner', 59.5, 67, 'Because our timeout was set to thirty seconds, waiting calls are keeping all our payment workers busy.', '[SRE] Do bên mình để timeout tới 30 giây nên các request chờ phản hồi đang chiếm kín hết luồng xử lý thanh toán.', 'keeping busy, payment workers', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-10', 'lesson-audio-itops-b1-09', 'owner', 67, 74.1, 'Can we lower the timeout to six seconds and show a polite retry message to users?', '[App Support] Mình hạ timeout xuống 6 giây rồi hiện thông báo mời khách thử lại nhẹ nhàng được không?', 'lower the timeout, retry message', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-11', 'lesson-audio-itops-b1-09', 'owner', 74.1, 80.8, 'Even better, we also have a backup payment service set up and ready for traffic.', '[SRE] Còn cách tốt hơn nữa, bên mình có cấu hình sẵn một cổng thanh toán dự phòng đang sẵn sàng nhận tải.', 'backup payment service, ready', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-12', 'lesson-audio-itops-b1-09', 'owner', 80.8, 88.8, 'Let us move fifty percent of checkout traffic to the backup service first and watch the success rate.', '[SRE] Mình chuyển trước 50% lưu lượng thanh toán sang cổng dự phòng rồi theo dõi tỷ lệ thành công nhé.', 'move traffic, success rate', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-13', 'lesson-audio-itops-b1-09', 'owner', 88.8, 95.5, 'Payments on the backup gateway are finishing in less than one second with zero timeouts.', '[App Support] Giao dịch qua cổng dự phòng xử lý chưa tới 1 giây và không bị lỗi timeout nào luôn.', 'finishing, zero timeouts', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-14', 'lesson-audio-itops-b1-09', 'owner', 95.5, 102.6, 'Great, I am moving one hundred percent of payment traffic over until the main partner recovers.', '[SRE] Tuyệt, mình chuyển toàn bộ 100% lưu lượng thanh toán sang bên đó cho tới khi đối tác chính hồi phục.', 'main partner, recovers', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-15', 'lesson-audio-itops-b1-09', 'owner', 102.6, 110.1, 'I also lowered the gateway timeout to eight seconds and added a safe limit on automatic retries.', '[SRE] Mình cũng hạ timeout của gateway xuống 8 giây và đặt thêm giới hạn an toàn cho các lần tự động thử lại.', 'automatic retries', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-16', 'lesson-audio-itops-b1-09', 'owner', 110.1, 116.8, 'Support tickets already stopped coming in, and payment success is back to its normal level.', '[App Support] Ticket báo lỗi ngừng đổ về rồi, tỷ lệ thanh toán thành công cũng quay về mức bình thường.', 'payment success, normal level', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-17', 'lesson-audio-itops-b1-09', 'owner', 116.8, 123.9, 'Let us keep an eye on the partner status page before switching traffic back tomorrow morning.', '[SRE] Mình cứ theo dõi trang trạng thái của họ trước khi chuyển lưu lượng quay lại vào sáng mai nhé.', 'keep an eye on, switching back', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-18', 'lesson-audio-itops-b1-09', 'owner', 123.9, 128.9, 'Agreed; having a tested backup gateway really saved our afternoon today.', '[App Support] Đồng ý luôn; có sẵn cổng dự phòng đã test kỹ đúng là cứu nguyên buổi chiều nay.', 'saved our afternoon', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-10', 'owner', 'audio-itops-b1-10', 'B1 | 10. Running a Weekly Incident Review & Runbook Update (IT Ops)', 'A 2-minute B1 team operations meeting reviewing weekly incidents, reducing noisy alerts, improving step-by-step guides, and helping new engineers (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-1', 'lesson-audio-itops-b1-10', 'owner', 0, 8, 'Welcome to our Friday operations review; let us look calmly at the two incidents we handled this week.', '[Ops Manager] Chào mọi người đến buổi họp tổng kết vận hành thứ Sáu; mình cùng nhìn lại hai sự cố đã xử lý tuần này nhé.', 'operations review, handled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-2', 'lesson-audio-itops-b1-10', 'owner', 8, 14.7, 'Total uptime stayed above ninety nine percent, though Tuesday’s night alert took longer than expected.', '[SysAdmin] Tổng thời gian hoạt động vẫn trên 99%, chỉ có cảnh báo tối thứ Ba xử lý hơi lâu hơn dự kiến.', 'total uptime, longer than expected', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-3', 'lesson-audio-itops-b1-10', 'owner', 14.7, 21, 'What slowed the response down on Tuesday when the queue server stopped processing jobs?', '[Ops Manager] Hôm thứ Ba lúc server hàng đợi ngừng chạy tác vụ thì điều gì làm mình xử lý chậm vậy?', 'slowed down, processing jobs', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-4', 'lesson-audio-itops-b1-10', 'owner', 21, 29.4, 'First, our monitoring chat received nearly forty small warnings that night, so the real problem was easy to miss.', '[SysAdmin] Thứ nhất, đêm đó kênh chat giám sát nổ gần 40 cảnh báo lặt vặt nên rất dễ bỏ sót lỗi thật.', 'small warnings, easy to miss', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-5', 'lesson-audio-itops-b1-10', 'owner', 29.4, 35.7, 'Second, the restart steps in our wiki were old after last month’s server upgrade.', '[SysAdmin] Thứ hai, các bước khởi động lại trên wiki đã cũ từ sau đợt nâng cấp server tháng trước.', 'restart steps, server upgrade', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-6', 'lesson-audio-itops-b1-10', 'owner', 35.7, 43.7, 'That is very clear feedback; noisy alerts tire out the on call team and slow down real fixes.', '[Ops Manager] Góp ý rất rõ ràng; cảnh báo nhiễu làm anh em trực ca bị mệt và chậm xử lý sự cố thật.', 'noisy alerts, tire out', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-7', 'lesson-audio-itops-b1-10', 'owner', 43.7, 51.7, 'Which of those forty small warnings can we safely turn off or put into a daily summary email?', '[Ops Manager] Trong 40 cảnh báo nhỏ đó, những cái nào mình có thể tắt bớt hoặc gom vào email tổng hợp hằng ngày?', 'turn off, daily summary', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-8', 'lesson-audio-itops-b1-10', 'owner', 51.7, 60.1, 'Short CPU jumps that last under thirty seconds never need to wake someone up at three in the morning.', '[SysAdmin] Mấy đợt CPU tăng vọt dưới 30 giây thì không bao giờ cần dựng anh em dậy lúc 3 giờ sáng cả.', 'CPU jumps, wake someone up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-9', 'lesson-audio-itops-b1-10', 'owner', 60.1, 69.3, 'Agreed; let us wait until high CPU stays above eighty five percent for five minutes before calling the on call engineer.', '[Ops Manager] Nhất trí; mình chỉnh thành CPU phải giữ trên 85% liên tục 5 phút thì mới gọi kỹ sư trực.', 'on call engineer, stays above', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-10', 'lesson-audio-itops-b1-10', 'owner', 69.3, 75.6, 'What about updating our incident guides so new shift engineers can follow them easily?', '[Ops Manager] Còn việc cập nhật tài liệu xử lý sự cố để các bạn trực ca mới dễ làm theo thì sao?', 'shift engineers, easily', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-11', 'lesson-audio-itops-b1-10', 'owner', 75.6, 82.7, 'I already rewrote the queue server guide with exact commands, expected results, and clear rollback steps.', '[SysAdmin] Mình đã viết lại hướng dẫn cho server hàng đợi rồi, có sẵn câu lệnh cụ thể, kết quả mong đợi và các bước quay lui rõ ràng.', 'exact commands, expected results', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-12', 'lesson-audio-itops-b1-10', 'owner', 82.7, 89.8, 'Can we ask one of our newer engineers to test that guide on staging next Tuesday?', '[Ops Manager] Thứ Ba tới mình nhờ một kỹ sư mới chạy thử theo tài liệu đó trên staging xem sao nhé?', 'newer engineers, test on staging', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-13', 'lesson-audio-itops-b1-10', 'owner', 89.8, 98.2, 'Great idea; if a new team member can follow every step smoothly, we know the document is really clear.', '[SysAdmin] Ý hay đấy; nếu thành viên mới làm trôi chảy từng bước thì chứng tỏ tài liệu thực sự dễ hiểu.', 'really clear, follow every step', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-14', 'lesson-audio-itops-b1-10', 'owner', 98.2, 104.1, 'Let us also link each monitoring alert directly to its matching guide page.', '[Ops Manager] Mình gắn luôn đường link tài liệu hướng dẫn tương ứng vào từng cảnh báo giám sát nhé.', 'link directly, matching guide', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-15', 'lesson-audio-itops-b1-10', 'owner', 104.1, 111.6, 'That saves important minutes during an urgent phone call because nobody has to search through old folders.', '[SysAdmin] Cách đó tiết kiệm được khối thời gian quý giá lúc xử lý khẩn cấp vì không phải lục tìm trong đống thư mục cũ.', 'important minutes, urgent phone call', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-16', 'lesson-audio-itops-b1-10', 'owner', 111.6, 117.9, 'Before we finish, is there any maintenance or risky release planned for next week?', '[Ops Manager] Trước khi kết thúc buổi họp, tuần tới có lịch bảo trì hay đợt cập nhật nào rủi ro không?', 'maintenance, planned', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-17', 'lesson-audio-itops-b1-10', 'owner', 117.9, 124.6, 'Only a normal security update on Wednesday evening, and backups are already checked and ready.', '[SysAdmin] Chỉ có đợt cập nhật bảo mật định kỳ tối thứ Tư thôi, backup cũng đã kiểm tra sẵn sàng hết rồi.', 'security update, checked and ready', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-18', 'lesson-audio-itops-b1-10', 'owner', 124.6, 131.3, 'Great work everyone; fewer noisy alerts and clearer guides will make next week much calmer.', '[Ops Manager] Cả team làm tốt lắm; bớt cảnh báo nhiễu với có tài liệu rõ ràng hơn sẽ giúp tuần tới nhẹ nhàng hơn nhiều.', 'much calmer', 17);
